// Previous versions of a post's title, excerpt and body, kept on every edit.
export const postRevisions = sqliteTable("post_revisions", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  postId: integer("post_id").notNull(),
  title: text("title").notNull(),
  excerpt: text("excerpt").notNull(),
  body: text("body").notNull(),
  createdAt: text("created_at").notNull().default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`),
});
EOF
cat >> lib/posts.ts <<'EOF'

/** Keeps the post's current title, excerpt and body as a revision, then applies `next`. */
export async function saveWithRevision(
  post: { id: number; title: string; excerpt: string; body: string },
  next: { title: string; excerpt: string; body: string },
): Promise<void> {
  await db.insert(postRevisions).values({
    postId: post.id,
    title: post.title,
    excerpt: post.excerpt,
    body: post.body,
  });
  await db
    .update(posts)
    .set({ title: next.title, excerpt: next.excerpt, body: next.body })
    .where(eq(posts.id, post.id));
}
EOF
