import { HTTPException } from "hono/http-exception";
import { defineHandler } from "void";
import { and, db, eq } from "void/db";
import { postRevisions } from "@schema";
import { userOrRedirect } from "../../../../../lib/guards";
import { authorizeAuthor, findPostOrFail, parsePostId, saveWithRevision } from "../../../../../lib/posts";
import { postIdSchema } from "../../../../../lib/validators";

export const POST = defineHandler(async (c) => {
  const user = userOrRedirect(c);
  if (user instanceof Response) return user;
  const post = await findPostOrFail(parsePostId(c.req.param("id")));
  authorizeAuthor(user, post);
  const parsed = postIdSchema.safeParse(c.req.param("revisionId"));
  if (!parsed.success) throw new HTTPException(404, { message: "Revision not found" });
  const [revision] = await db
    .select()
    .from(postRevisions)
    .where(and(eq(postRevisions.id, parsed.data), eq(postRevisions.postId, post.id)));
  if (!revision) throw new HTTPException(404, { message: "Revision not found" });
  await saveWithRevision(post, revision);
  return c.redirect(`/posts/${post.id}`);
});
EOF
cat > "pages/posts/[id]/revisions.server.ts" <<'EOF'
import { defineHandler, type InferProps } from "void";
import { desc, db, eq } from "void/db";
import { postRevisions } from "@schema";
import { userOrRedirect } from "../../../lib/guards";
import { authorizeAuthor, findPostOrFail, parsePostId } from "../../../lib/posts";

export type Props = InferProps<typeof loader>;

export const loader = defineHandler(async (c) => {
  const user = userOrRedirect(c);
  if (user instanceof Response) return user;
  const post = await findPostOrFail(parsePostId(c.req.param("id")));
  authorizeAuthor(user, post);
  const revisions = await db
    .select({ id: postRevisions.id, title: postRevisions.title, createdAt: postRevisions.createdAt })
    .from(postRevisions)
    .where(eq(postRevisions.postId, post.id))
    .orderBy(desc(postRevisions.createdAt), desc(postRevisions.id));
  return { post: { id: post.id, title: post.title }, revisions };
});
EOF
cat > "pages/posts/[id]/revisions.tsx" <<'EOF'
import { Link } from "@void/react";
import type { Props } from "./revisions.server";

export default function PostRevisions({ post, revisions }: Props) {
  async function restore(revisionId: number) {
    if (!confirm("Restore this revision?")) return;
    const res = await fetch(`/posts/${post.id}/revisions/${revisionId}/restore`, { method: "POST" });
    window.location.href = res.ok ? `/posts/${post.id}` : window.location.href;
  }

  return (
    <section>
      <h1>Revisions of {post.title}</h1>
      <p>
        <Link href={`/posts/${post.id}`}>Back to post</Link>
      </p>
      {revisions.length === 0 && <p>No revisions yet.</p>}
      <ul>
        {revisions.map((r) => (
          <li key={r.id}>
            {r.title} · <small>{new Date(r.createdAt).toLocaleString()}</small>{" "}
            <button type="button" onClick={() => restore(r.id)}>Restore</button>
          </li>
        ))}
      </ul>
    </section>
  );
}
EOF
